const ILC_FL =[0,0,0,0,3];        // 눈송이                               ←원본 3
const ILC_SPK=[0,2,4,6,8];        // 반짝이                               ←원본 8

// ── ⑤ 빙벽 — 레벨 표 ─────────────────────────────────────────────────────
// 축 = **버팀**. 칸마다 사건 하나:
